var util = require('util');
var carrier = require('carrier');

var DEFAULT_FIFO ='/tmp/wifiFIFO';

var DB= 'dB';
var BSSID = 'BSSID:';

var endsWith = function(str, suffix) {
    return (str.indexOf(suffix, str.length - suffix.length) !== -1);
};

var startsWith = function(str, prefix) {
    return (str.indexOf(prefix) === 0);
};

var WifiEmitter = exports.WifiEmitter = function(spec) {
    var self = this;
    events.EventEmitter.call(this);
    this.wifiFIFO = (spec && spec.wifiFIFO) || DEFAULT_FIFO;
    this.fifo = fs.createReadStream(this.wifiFIFO);
    this.fifo.on('error', function(err) { self.emit('error', err);});
    carrier.carry(this.fifo, function(line) {
                      var splitLine = line.split(/ +/);
                      var timestamp = null;
                      var signal = null;
                      var source = null;
                      /* 1384912098.012519 11.0 Mb/s 2462 MHz 11b -63dB 
                       * signal antenna 2 BSSID:2c:76:8a:f9:b4:72  ...*/
                      splitLine
                          .forEach(function(x, i) {
                                       if (i === 0) {
                                           timestamp = Math.floor(parseFloat(x)
                                                                  * 1000.0);
                                       } else if (endsWith(x, DB))  {
                                           var xT = x.substring(0, x.length
                                                                - DB.length);
                                           signal = parseInt(xT);
                                       } else if (startsWith(x, BSSID)) {
                                           source = x.substring(BSSID.length,
                                                                x.length);
                                       }
                                   });
                      if (timestamp && signal && source) {
                          self.emit('wifiData', {timestamp: timestamp,
                                                 signal: signal,
                                                 source: source});
                      }
                  });
};

util.inherits(WifiEmitter, events.EventEmitter);

WifiEmitter.prototype.shutdown = function() {
    this.fifo && this.fifo.close();
    this.emit('close');
